// Data Archival Engine for {{CLINIC_NAME}}
const now = new Date();
const timezone = '{{TIMEZONE}}';
const archiveThresholdYears = {{DATA_RETENTION_YEARS}} || 5;

console.log(`🗂️ Starting data archival process for {{CLINIC_NAME}} - ${now.toLocaleString('en-US', { timeZone: timezone })}`);

// Calculate cutoff date for archival
const archiveCutoffDate = new Date();
archiveCutoffDate.setFullYear(archiveCutoffDate.getFullYear() - archiveThresholdYears);

console.log(`📅 Archiving records older than: ${archiveCutoffDate.toLocaleDateString('en-US', { timeZone: timezone })}`);

// Get all appointment records
const allAppointments = $input.all().map(item => item.json);
console.log(`📋 Total appointments found: ${allAppointments.length}`);

// Filter appointments for archival based on date
const appointmentsToArchive = allAppointments.filter(appointment => {
  // Try multiple date field formats
  const dateFields = [
    appointment['Date'],
    appointment['Appointment Date'],
    appointment['AppointmentDate'],
    appointment['DateTime'],
    appointment['AppointmentDateTime'],
    appointment['Created'],
    appointment['Timestamp']
  ];

  let appointmentDate = null;

  // Find the first valid date field
  for (const dateField of dateFields) {
    if (dateField) {
      const parsedDate = new Date(dateField);
      if (!isNaN(parsedDate.getTime())) {
        appointmentDate = parsedDate;
        break;
      }
    }
  }

  // If no valid date found, skip archival for safety
  if (!appointmentDate) {
    console.log(`⚠️ No valid date found for appointment: ${appointment['Customer Name'] || appointment['Client Name'] || 'Unknown'}`);
    return false;
  }

  // Check if appointment is older than cutoff date
  const shouldArchive = appointmentDate < archiveCutoffDate;

  if (shouldArchive) {
    console.log(`🗃️ Marking for archive: ${appointment['Customer Name'] || appointment['Client Name']} - ${appointmentDate.toLocaleDateString()}`);
  }

  return shouldArchive;
});

console.log(`🗂️ Found ${appointmentsToArchive.length} appointments ready for archival`);

// Prepare archival data with metadata
const archivalResults = {
  timestamp: now.toISOString(),
  clinic_name: '{{CLINIC_NAME}}',
  archive_process: 'Monthly Data Archival',
  cutoff_date: archiveCutoffDate.toISOString(),
  total_records_processed: allAppointments.length,
  records_to_archive: appointmentsToArchive.length,
  archive_threshold_years: archiveThresholdYears,
  appointments_to_archive: appointmentsToArchive
};

// Generate summary report
if (appointmentsToArchive.length > 0) {
  archivalResults.status = 'ARCHIVAL_REQUIRED';
  archivalResults.summary = `Found ${appointmentsToArchive.length} appointments from ${allAppointments.length} total records that need to be archived (older than ${archiveThresholdYears} years).`;

  // Group by year for reporting
  const archiveByYear = {};
  appointmentsToArchive.forEach(apt => {
    const dateFields = [apt['Date'], apt['Appointment Date'], apt['AppointmentDate'], apt['DateTime'], apt['AppointmentDateTime'], apt['Created'], apt['Timestamp']];
    let year = 'Unknown';

    for (const dateField of dateFields) {
      if (dateField) {
        const parsedDate = new Date(dateField);
        if (!isNaN(parsedDate.getTime())) {
          year = parsedDate.getFullYear();
          break;
        }
      }
    }

    archiveByYear[year] = (archiveByYear[year] || 0) + 1;
  });

  archivalResults.archive_breakdown = archiveByYear;
} else {
  archivalResults.status = 'NO_ARCHIVAL_NEEDED';
  archivalResults.summary = 'All appointment records are within the retention period. No archival required at this time.';
}

console.log(`📊 Archival summary: ${archivalResults.summary}`);

// Return results - appointments to archive will be processed by next nodes
return [{ json: archivalResults }];

// Prepare records for archival with enhanced metadata
const archivalData = $json.appointments_to_archive || [];
const now = new Date();
const timezone = '{{TIMEZONE}}';

console.log(`🗃️ Preparing ${archivalData.length} records for archival to Google Sheets`);

// Enhance each record with archival metadata
const enhancedRecords = archivalData.map((record, index) => {
  return {
    ...record,
    'Archive Date': now.toISOString(),
    'Archive Reason': 'Automatic {{DATA_RETENTION_YEARS}}-year retention policy',
    'Archive Process': 'ETF Monthly Data Archival',
    'Clinic Name': '{{CLINIC_NAME}}',
    'Archive Index': index + 1,
    'Original Source': 'Master Appointments Hub'
  };
});

console.log(`✅ Enhanced ${enhancedRecords.length} records with archival metadata`);

// Return each record as a separate item for Google Sheets processing
return enhancedRecords.map(record => ({ json: record }));

// Generate cleanup summary after successful archival
const archivalSummary = $('📋 Archive Required?').first().json;
const archivedCount = $input.all().length;

console.log(`🧹 Successfully archived ${archivedCount} records. Preparing cleanup summary.`);

const cleanupResults = {
  timestamp: new Date().toISOString(),
  clinic_name: '{{CLINIC_NAME}}',
  cleanup_process: 'Post-Archive Data Cleanup',
  records_archived: archivedCount,
  archive_successful: true,
  next_steps: 'Records have been safely archived and are ready for removal from active database',
  archive_location: '{{ARCHIVE_SHEET_ID}}',
  retention_policy: '{{DATA_RETENTION_YEARS}} years',
  status: 'CLEANUP_READY'
};

console.log(`✅ Archive completed successfully. ${archivedCount} records moved to archive.`);

return [{ json: cleanupResults }];
